// src/app/compare/AdvancedAnalysis.tsx
'use client';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  reviews: number;
  inStock: boolean;
}

interface Props {
  products: Product[];
}

// Native implementations of statistical functions (replacing mathjs)
function mean(values: number[]): number {
  return values.reduce((sum, val) => sum + val, 0) / values.length;
}

function median(values: number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function variance(values: number[]): number {
  const avg = mean(values);
  return values.reduce((sum, val) => sum + Math.pow(val - avg, 2), 0) / values.length;
}

function std(values: number[]): number {
  return Math.sqrt(variance(values));
}

function quantile(values: number[], q: number): number {
  const sorted = [...values].sort((a, b) => a - b);
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
  }
  return sorted[base];
}

export default function AdvancedAnalysis({ products }: Props) {
  const prices = products.map(p => p.price);
  const ratings = products.map(p => p.rating);
  const reviews = products.map(p => p.reviews);

  const priceStats = {
    mean: mean(prices),
    median: median(prices),
    std: std(prices),
    variance: variance(prices),
    q1: quantile(prices, 0.25),
    q3: quantile(prices, 0.75),
  };

  const ratingStats = {
    mean: mean(ratings),
    median: median(ratings),
    std: std(ratings),
  };

  const reviewStats = {
